const { shell } = require("uxp");
const { storage } = require("uxp");
const localStorage = storage.secureStorage;

function decodeStoredText(e) {
  let t = "";
  let n = 0;
  while (n < e.length) {
    const a = e[n];
    let o = 1;
    let i = a;
    if (a >= 194 && a <= 223) {
      o = 2;
      i = a & 31;
    } else if (a >= 224 && a <= 239) {
      o = 3;
      i = a & 15;
    } else if (a >= 240 && a <= 244) {
      o = 4;
      i = a & 7;
    } else if (a >= 128) {
      t += "\uFFFD";
      n += 1;
      continue;
    }
    if (n + o > e.length) {
      t += "\uFFFD";
      break;
    }
    let s = true;
    for (let r = 1; r < o; r++) {
      const c = e[n + r];
      if ((c & 192) !== 128) {
        s = false;
        break;
      }
      i = (i << 6) | (c & 63);
    }
    if (!s) {
      t += "\uFFFD";
      n += 1;
      continue;
    }
    t += String.fromCodePoint(i);
    n += o;
  }
  return t;
}

async function readStoredText(e) {
  try {
    const t = await localStorage.getItem(e);
    return t ? decodeStoredText(t) : null;
  } catch (t) {
    console.warn(`Could not read ${e} from secure storage; treating it as missing.`, t);
    return null;
  }
}

async function storeText(e, t) {
  try {
    await localStorage.setItem(e, t);
  } catch (n) {
    console.warn(`Could not write ${e} to secure storage; replacing the entry.`, n);
    await localStorage.removeItem(e).catch(() => {});
    await localStorage.setItem(e, t);
  }
}

const LOCAL_STORAGE_API_KEY = "openrouter_api_key";

window.astriaOAuth = {
  authenticated: () => true,
  snapshot: () => ({
    status: "connected",
    message: "Connected with OpenRouter AI",
    user: { email: "openrouter@nano-banana.ai", name: "Astria Pro" }
  }),
  restore: async () => true,
  start: () => {},
  cancel: () => {},
  signOut: async () => {
    await removeGeminiApiKey();
  },
  rejected: async () => {}
};

window.USER_BALANCE_MC = 0;
let currentBalanceNumeric = 0;
let lastBalanceDeductionTime = 0;

function deductOpenRouterBalance(cost) {
  const numericCost = typeof cost === "number" ? cost : (cost ? parseFloat(String(cost).replace(/[^0-9.]/g, "")) : 0);
  if (numericCost > 0 && currentBalanceNumeric > 0) {
    currentBalanceNumeric = Math.max(0, currentBalanceNumeric - numericCost);
    lastBalanceDeductionTime = Date.now();
    const formatted = "$" + currentBalanceNumeric.toFixed(2);
    const balanceEl = document.getElementById("user-balance");
    if (balanceEl) balanceEl.textContent = formatted;
    window.USER_BALANCE_MC = Math.round(currentBalanceNumeric * 1e5);
    if (window.nanoBananaPayer) {
      window.nanoBananaPayer.usd_balance_mc = window.USER_BALANCE_MC;
    }
    console.log("[Balance] Immediate deduction: -$" + numericCost.toFixed(4) + " => " + formatted);
    window.nanoBananaBridge?.refresh();
  }
}
window.deductOpenRouterBalance = deductOpenRouterBalance;

async function updateUserBalance(force = false) {
  if (force) {
    lastBalanceDeductionTime = 0;
  }
  let info = { balance: "$0.00", numeric: 0, label: "OpenRouter" };
  try {
    const fetchFn = window.fetchOpenRouterBalance || (typeof fetchOpenRouterBalance === "function" ? fetchOpenRouterBalance : null);
    if (fetchFn) {
      info = await fetchFn();
    }
  } catch (e) {
    console.warn("[Balance] Could not retrieve balance from OpenRouter:", e);
  }

  const serverNumericUsd = typeof info.numeric === "number" ? info.numeric : 0;
  const timeSinceDeduction = Date.now() - lastBalanceDeductionTime;

  if (lastBalanceDeductionTime > 0 && timeSinceDeduction < 6000 && serverNumericUsd > currentBalanceNumeric) {
    console.log("[Balance] OpenRouter ledger not updated yet ($" + serverNumericUsd.toFixed(2) + " > $" + currentBalanceNumeric.toFixed(2) + " within " + timeSinceDeduction + "ms). Preserving optimistic balance.");
  } else {
    currentBalanceNumeric = serverNumericUsd;
  }

  const displayBalance = "$" + currentBalanceNumeric.toFixed(2);
  const displayLabel = info.label || "OpenRouter AI";

  window.nanoBananaUser = { name: displayLabel, email: displayLabel };
  window.nanoBananaPayer = { name: displayLabel, self: true, usd_balance_mc: Math.round(currentBalanceNumeric * 1e5) };
  window.USER_BALANCE_MC = Math.round(currentBalanceNumeric * 1e5);

  const balanceEl = document.getElementById("user-balance");
  if (balanceEl) balanceEl.textContent = displayBalance;
  const emailEl = document.getElementById("user-email");
  if (emailEl) emailEl.textContent = displayLabel;

  console.log("[OpenRouter Balance] Updated: " + displayBalance + " (" + displayLabel + ")");
  window.nanoBananaBridge?.refresh();
}
window.updateUserBalance = updateUserBalance;

async function initAuth() {
  console.log("[Auth] Initializing OpenRouter Astria plugin...");
  window.nanoBananaAuthReady = false;
  window.nanoBananaInitializationError = "";
  window.nanoBananaAgentEnabled = false;
  window.nanoBananaBridge?.closeChat();
  window.nanoBananaBridge?.refresh();

  await initGeminiSdk();

  const authSection = document.getElementById("auth");
  if (authSection) authSection.classList.add("hidden");
  const mainSection = document.getElementById("main");
  if (mainSection) mainSection.classList.remove("hidden");

  await updateUserBalance();

  try {
    await initializeModels();
  } catch (t) {
    console.error("[Auth] Model initialization error:", t);
  }

  window.nanoBananaAuthReady = true;
  window.nanoBananaBridge?.refresh();
}

async function signout(e) {
  e?.preventDefault();
  await removeGeminiApiKey();
  await initAuth();
}

async function submitAuth() {
  await initAuth();
}

document.addEventListener("DOMContentLoaded", () => {
  document.getElementById("signout")?.addEventListener("click", signout);
  document.getElementById("submit-auth")?.addEventListener("click", submitAuth);
  document.getElementById("cancel-auth")?.addEventListener("click", () => window.astriaOAuth.cancel());
  setTimeout(initAuth, 50);
});
